package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.exceptions.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class KeyedObjects2D_removeColumn_TriageGen2Test {

    private KeyedObjects2D dataset;
    private static final Comparable ROW_KEY_1 = "Row1";
    private static final Comparable ROW_KEY_2 = "Row2";
    private static final Comparable COL_KEY_1 = "Col1";
    private static final Comparable COL_KEY_2 = "Col2";
    private static final Comparable INVALID_COL_KEY = "InvalidCol";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test(expected = UnknownKeyException.class)
    public void testRemoveColumn_UnknownKeyThrowsException() {
        // index will be < 1 if key is not found (assuming getColumnIndex returns 0 or -1 for unknown)
        dataset.removeColumn(INVALID_COL_KEY);
    }

    @Test
    public void testRemoveColumn_ExistingColumnRemovesDataAndKey() {
        // Setup data
        dataset.addObject("Val1_1", ROW_KEY_1, COL_KEY_1);
        dataset.addObject("Val1_2", ROW_KEY_1, COL_KEY_2);
        dataset.addObject("Val2_1", ROW_KEY_2, COL_KEY_1);
        dataset.addObject("Val2_2", ROW_KEY_2, COL_KEY_2);

        // Verify initial state
        assertEquals(2, dataset.getColumnCount());
        assertEquals("Val1_1", dataset.getObject(ROW_KEY_1, COL_KEY_1));

        // Execute
        dataset.removeColumn(COL_KEY_1);

        // Verify column key is removed
        List<Comparable> columnKeys = dataset.getColumnKeys();
        assertFalse("Column key should be removed", columnKeys.contains(COL_KEY_1));
        assertTrue("Other column key should remain", columnKeys.contains(COL_KEY_2));
        assertEquals(1, dataset.getColumnCount());

        // Verify data is removed from rows
        // Depending on implementation of KeyedObjects, getObject might return null or throw exception
        // Based on the code, rowData.removeValue(i) is called.
        assertNull("Value for removed column should be null", dataset.getObject(ROW_KEY_1, COL_KEY_1));
        assertEquals("Val1_2", dataset.getObject(ROW_KEY_1, COL_KEY_2));
        assertNull("Value for removed column should be null", dataset.getObject(ROW_KEY_2, COL_KEY_1));
        assertEquals("Val2_2", dataset.getObject(ROW_KEY_2, COL_KEY_2));
    }

    @Test
    public void testRemoveColumn_ColumnWithNoDataInSomeRows() {
        // Setup data where one row doesn't contain the column key index
        // This tests the 'if (i >= 0)' branch
        dataset.addObject("Val1_1", ROW_KEY_1, COL_KEY_1);
        // Row 2 does not have COL_KEY_1
        dataset.addObject("Val2_2", ROW_KEY_2, COL_KEY_2);

        dataset.removeColumn(COL_KEY_1);

        assertEquals(1, dataset.getColumnCount());
        assertNull(dataset.getObject(ROW_KEY_1, COL_KEY_1));
        assertEquals("Val2_2", dataset.getObject(ROW_KEY_2, COL_KEY_2));
    }

    @Test
    public void testRemoveColumn_EmptyDataset() {
        // Test behavior when dataset is empty
        // Note: if getColumnIndex returns < 1 for empty, it hits the exception.
        // If it returns 0 for an empty set, it hits the exception.
        try {
            dataset.removeColumn(COL_KEY_1);
        } catch (UnknownKeyException e) {
            // Expected behavior for empty dataset
        }
    }
}
